#include <vector>
#include <algorithm>
#include <iostream>

template<typename InputIterator, typename ForwardIterator, typename BinaryPredicate>
ForwardIterator copy_if_with_predicate(InputIterator first, InputIterator last, ForwardIterator result, BinaryPredicate pred) {
    while (first != last) {
        if (pred(*first)) {
            *result++ = *first;
        }
        ++first;
    }
    return result;
}

int main() {
    std::vector<int> source = {1, 2, 3, 4, 5, 6};
    std::vector<int> filtered;
    filtered.reserve(source.size());
    auto is_even = [](int n) { return n % 2 == 0; };
    auto end_iter = copy_if_with_predicate(source.begin(), source.end(), std::back_inserter(filtered), is_even);
    std::cout << "Filtered even numbers: ";
    for (auto it = filtered.begin(); it != end_iter; ++it) {
        std::cout << *it << " ";
    }
    std::cout << std::endl;
    return 0;
}
